    caption: "A register entry that says only \"AI-generated\" has no evidence behind it.",
    afterParagraph: 10,
    svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 263\" width=\"800\" height=\"263\" role=\"img\" aria-labelledby=\"t\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"><title id=\"t\">A traceable risk entry: Evidence; AI proposal; Risk owner decides; Register entry</title><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L0,10 L9,5 Z\" fill=\"#9CA3AF\"/></marker></defs><rect width=\"800\" height=\"263\" fill=\"#F9FAFB\"/><text x=\"24.0\" y=\"40.0\" font-size=\"20\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">A traceable risk entry</text><rect x=\"24.0\" y=\"72.0\" width=\"162.5\" height=\"165.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"105.2\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"105.2\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">1</text><text x=\"105.2\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Evidence</text><text x=\"105.2\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Incident record,</text><text x=\"105.2\" y=\"187.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">audit finding,</text><text x=\"105.2\" y=\"204.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">supplier response,</text><text x=\"105.2\" y=\"221.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">test result</text><rect x=\"220.5\" y=\"72.0\" width=\"162.5\" height=\"165.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"301.8\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"301.8\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">2</text><text x=\"301.8\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">AI proposal</text><text x=\"301.8\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">A risk or rating,</text><text x=\"301.8\" y=\"187.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">noting what it was</text><text x=\"301.8\" y=\"204.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">based on</text><line x1=\"189.5\" y1=\"154.8\" x2=\"216.5\" y2=\"154.8\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><rect x=\"417.0\" y=\"72.0\" width=\"162.5\" height=\"165.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"498.2\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"498.2\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">3</text><text x=\"498.2\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Risk owner</text><text x=\"498.2\" y=\"164.5\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">decides</text><text x=\"498.2\" y=\"189.5\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Confirms, changes or</text><text x=\"498.2\" y=\"206.5\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">rejects it</text><line x1=\"386.0\" y1=\"154.8\" x2=\"413.0\" y2=\"154.8\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><rect x=\"613.5\" y=\"72.0\" width=\"162.5\" height=\"165.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"694.8\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"694.8\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">4</text><text x=\"694.8\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Register entry</text><text x=\"694.8\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Shows the source and</text><text x=\"694.8\" y=\"187.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">who confirmed it</text><line x1=\"582.5\" y1=\"154.8\" x2=\"609.5\" y2=\"154.8\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/></svg>",
