    svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 397\" width=\"800\" height=\"397\" role=\"img\" aria-labelledby=\"t\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"><title id=\"t\">Testing a prompt before it goes in the library: Test on real examples; Have someone else use it; Check against the checklist; Record what failed; Re-test</title><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L0,10 L9,5 Z\" fill=\"#9CA3AF\"/></marker></defs><rect width=\"800\" height=\"397\" fill=\"#F9FAFB\"/><text x=\"24.0\" y=\"40.0\" font-size=\"20\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">Testing a prompt before it goes in the library</text><rect x=\"24.0\" y=\"72.0\" width=\"228.0\" height=\"134.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"138.0\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"138.0\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">1</text><text x=\"138.0\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Test on real examples</text><text x=\"138.0\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">At least five allowed ones,</text><text x=\"138.0\" y=\"187.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">including a difficult one</text><rect x=\"286.0\" y=\"72.0\" width=\"228.0\" height=\"134.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"400.0\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"400.0\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">2</text><text x=\"400.0\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Have someone else use it</text><text x=\"400.0\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Different quality means unclear</text><text x=\"400.0\" y=\"187.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">instructions</text><line x1=\"255.0\" y1=\"139.0\" x2=\"282.0\" y2=\"139.0\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><rect x=\"548.0\" y=\"72.0\" width=\"228.0\" height=\"134.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"662.0\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"662.0\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">3</text><text x=\"662.0\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Check against the</text><text x=\"662.0\" y=\"164.5\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">checklist</text><text x=\"662.0\" y=\"189.5\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Every time</text><line x1=\"517.0\" y1=\"139.0\" x2=\"544.0\" y2=\"139.0\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><rect x=\"155.0\" y=\"240.0\" width=\"228.0\" height=\"131.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"269.0\" cy=\"268.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"269.0\" y=\"273.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">4</text><text x=\"269.0\" y=\"313.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Record what failed</text><text x=\"269.0\" y=\"338.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">And improve the template</text><rect x=\"417.0\" y=\"240.0\" width=\"228.0\" height=\"131.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"531.0\" cy=\"268.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"531.0\" y=\"273.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">5</text><text x=\"531.0\" y=\"313.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Re-test</text><text x=\"531.0\" y=\"338.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">When the tool changes, or every</text><text x=\"531.0\" y=\"355.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">few months</text><line x1=\"386.0\" y1=\"305.8\" x2=\"413.0\" y2=\"305.8\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><path d=\"M662.0,208.0 V226.0 H269.0 V236.0\" fill=\"none\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/></svg>",
