    courseSlug: "ai-workflow-productivity",
    moduleNumber: 6,
    lessonTitle: "Spreadsheets, analysis and trends",
    caption: "Ask all four before you share any AI analysis. AI often offers confident reasons the data cannot prove.",
    afterParagraph: 11,
    svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 254\" width=\"800\" height=\"254\" role=\"img\" aria-labelledby=\"t\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"><title id=\"t\">The data check: four questions: Source; Method; Reasonableness; Explanation</title><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L0,10 L9,5 Z\" fill=\"#9CA3AF\"/></marker></defs><rect width=\"800\" height=\"254\" fill=\"#F9FAFB\"/><text x=\"24.0\" y=\"40.0\" font-size=\"20\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">The data check: four questions</text><rect x=\"24.0\" y=\"72.0\" width=\"177.5\" height=\"156.1\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"112.8\" cy=\"104.0\" r=\"22\" fill=\"#EFF6FF\"/><g transform=\"translate(112.8,104.0)\"><path d=\"M-8,-11 H3 L8,-6 V11 H-8 Z\" fill=\"none\" stroke=\"#2563EB\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M-4,-2 H4 M-4,2 H4 M-4,6 H1\" fill=\"none\" stroke=\"#2563EB\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><text x=\"112.8\" y=\"151.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Source</text><text x=\"112.8\" y=\"175.9\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Which exact data? The</text><text x=\"112.8\" y=\"192.8\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">latest, complete</text><text x=\"112.8\" y=\"209.6\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">version?</text><rect x=\"215.5\" y=\"72.0\" width=\"177.5\" height=\"156.1\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"304.2\" cy=\"104.0\" r=\"22\" fill=\"#EFF6FF\"/><g transform=\"translate(304.2,104.0)\"><circle cx=\"0\" cy=\"0\" r=\"4\" fill=\"none\" stroke=\"#2563EB\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"0\" cy=\"0\" r=\"9\" fill=\"none\" stroke=\"#2563EB\" stroke-width=\"4\" stroke-dasharray=\"4 3\"/></g><text x=\"304.2\" y=\"151.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Method</text><text x=\"304.2\" y=\"175.9\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">How was each figure</text><text x=\"304.2\" y=\"192.8\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">calculated? Can I</text><text x=\"304.2\" y=\"209.6\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">repeat it?</text><rect x=\"407.0\" y=\"72.0\" width=\"177.5\" height=\"156.1\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"495.8\" cy=\"104.0\" r=\"22\" fill=\"#EFF6FF\"/><g transform=\"translate(495.8,104.0)\"><path d=\"M0,-11 V10 M-7,10 H7 M-11,-6 H11 M-11,-6 L-14,2 H-8 Z M11,-6 L8,2 H14 Z\" fill=\"none\" stroke=\"#2563EB\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><text x=\"495.8\" y=\"151.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Reasonableness</text><text x=\"495.8\" y=\"175.9\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Does it make sense? A</text><text x=\"495.8\" y=\"192.8\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">400% rise should make</text><text x=\"495.8\" y=\"209.6\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">you suspicious.</text><rect x=\"598.5\" y=\"72.0\" width=\"177.5\" height=\"156.1\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"687.2\" cy=\"104.0\" r=\"22\" fill=\"#EFF6FF\"/><g transform=\"translate(687.2,104.0)\"><circle cx=\"-3\" cy=\"-3\" r=\"7\" fill=\"none\" stroke=\"#2563EB\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M2,2 L10,10\" fill=\"none\" stroke=\"#2563EB\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><text x=\"687.2\" y=\"151.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Explanation</text><text x=\"687.2\" y=\"175.9\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Is the reason for a</text><text x=\"687.2\" y=\"192.8\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">trend supported by</text><text x=\"687.2\" y=\"209.6\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">evidence, or a guess?</text></svg>",
