    moduleNumber: 8,
    lessonTitle: "Confidentiality and data protection",
    caption: "If your organisation has its own labels, use them. If not, this simple check works.",
    afterParagraph: 13,
    svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 290\" width=\"800\" height=\"290\" role=\"img\" aria-labelledby=\"t\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"><title id=\"t\">Classify before you type: the traffic-light check: Green: public; Amber: internal; Red: confidential or personal</title><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L0,10 L9,5 Z\" fill=\"#9CA3AF\"/></marker></defs><rect width=\"800\" height=\"290\" fill=\"#F9FAFB\"/><text x=\"24.0\" y=\"40.0\" font-size=\"20\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">Classify before you type: the traffic-light check</text><rect x=\"24.0\" y=\"72.0\" width=\"752.0\" height=\"45.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"24.0\" y=\"72.0\" width=\"196\" height=\"45.5\" rx=\"10\" fill=\"#E8F5EC\"/><rect x=\"24.0\" y=\"72.0\" width=\"8\" height=\"45.5\" rx=\"4\" fill=\"#15803D\"/><text x=\"46.0\" y=\"99.8\" font-size=\"15\" fill=\"#15803D\" font-weight=\"700\" text-anchor=\"start\">Green: public</text><text x=\"236.0\" y=\"99.8\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Published website text, public reports, press releases. Any approved tool.</text><rect x=\"24.0\" y=\"127.5\" width=\"752.0\" height=\"62.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"24.0\" y=\"127.5\" width=\"196\" height=\"62.0\" rx=\"10\" fill=\"#FDF3E3\"/><rect x=\"24.0\" y=\"127.5\" width=\"8\" height=\"62.0\" rx=\"4\" fill=\"#B45309\"/><text x=\"46.0\" y=\"163.5\" font-size=\"15\" fill=\"#B45309\" font-weight=\"700\" text-anchor=\"start\">Amber: internal</text><text x=\"236.0\" y=\"154.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Internal procedures, non-sensitive meeting notes, draft internal</text><text x=\"236.0\" y=\"172.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">communications. Approved business tools only.</text><rect x=\"24.0\" y=\"199.5\" width=\"752.0\" height=\"65.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"24.0\" y=\"199.5\" width=\"196\" height=\"65.0\" rx=\"10\" fill=\"#FBEAE6\"/><rect x=\"24.0\" y=\"199.5\" width=\"8\" height=\"65.0\" rx=\"4\" fill=\"#C1442D\"/><text x=\"46.0\" y=\"227.2\" font-size=\"15\" fill=\"#C1442D\" font-weight=\"700\" text-anchor=\"start\">Red: confidential or</text><text x=\"46.0\" y=\"246.8\" font-size=\"15\" fill=\"#C1442D\" font-weight=\"700\" text-anchor=\"start\">personal</text><text x=\"236.0\" y=\"228.0\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Personal data, health information, unpublished results, contracts, bids,</text><text x=\"236.0\" y=\"246.0\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">passwords. Only tools specifically approved for it.</text></svg>",
