    caption: "Not every output needs the same level of checking. Match the effort to what could go wrong.",
    afterParagraph: 5,
    svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 305\" width=\"800\" height=\"305\" role=\"img\" aria-labelledby=\"t\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"><title id=\"t\">Match the check to the risk: Low; Medium; High</title><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L0,10 L9,5 Z\" fill=\"#9CA3AF\"/></marker></defs><rect width=\"800\" height=\"305\" fill=\"#F9FAFB\"/><text x=\"24.0\" y=\"40.0\" font-size=\"20\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">Match the check to the risk</text><rect x=\"24.0\" y=\"72.0\" width=\"752.0\" height=\"45.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"24.0\" y=\"72.0\" width=\"196\" height=\"45.5\" rx=\"10\" fill=\"#E8F5EC\"/><rect x=\"24.0\" y=\"72.0\" width=\"8\" height=\"45.5\" rx=\"4\" fill=\"#15803D\"/><text x=\"46.0\" y=\"99.8\" font-size=\"15\" fill=\"#15803D\" font-weight=\"700\" text-anchor=\"start\">Low</text><text x=\"236.0\" y=\"99.8\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Brainstormed ideas, internal draft notes. Read it and use your judgement.</text><rect x=\"24.0\" y=\"127.5\" width=\"752.0\" height=\"62.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"24.0\" y=\"127.5\" width=\"196\" height=\"62.0\" rx=\"10\" fill=\"#FDF3E3\"/><rect x=\"24.0\" y=\"127.5\" width=\"8\" height=\"62.0\" rx=\"4\" fill=\"#B45309\"/><text x=\"46.0\" y=\"163.5\" font-size=\"15\" fill=\"#B45309\" font-weight=\"700\" text-anchor=\"start\">Medium</text><text x=\"236.0\" y=\"154.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Internal reports, team communications, data summaries. Check all facts,</text><text x=\"236.0\" y=\"172.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">figures and names against sources.</text><rect x=\"24.0\" y=\"199.5\" width=\"752.0\" height=\"80.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"24.0\" y=\"199.5\" width=\"196\" height=\"80.0\" rx=\"10\" fill=\"#FBEAE6\"/><rect x=\"24.0\" y=\"199.5\" width=\"8\" height=\"80.0\" rx=\"4\" fill=\"#C1442D\"/><text x=\"46.0\" y=\"244.5\" font-size=\"15\" fill=\"#C1442D\" font-weight=\"700\" text-anchor=\"start\">High</text><text x=\"236.0\" y=\"226.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Anything for customers, regulators, the board or the public; money,</text><text x=\"236.0\" y=\"244.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">safety, legal or people decisions. Full source check, second reviewer,</text><text x=\"236.0\" y=\"262.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">expert where needed.</text></svg>",
