    svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 293\" width=\"800\" height=\"293\" role=\"img\" aria-labelledby=\"t\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"><title id=\"t\">Safer ways to connect in public: 1. Your phone's hotspot; 2. Public Wi-Fi + VPN; 3. No connection</title><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L0,10 L9,5 Z\" fill=\"#9CA3AF\"/></marker></defs><rect width=\"800\" height=\"293\" fill=\"#F9FAFB\"/><text x=\"24.0\" y=\"40.0\" font-size=\"20\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">Safer ways to connect in public</text><rect x=\"58.0\" y=\"72.0\" width=\"718.0\" height=\"65.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"58.0\" y=\"72.0\" width=\"196\" height=\"65.0\" rx=\"10\" fill=\"#E8F5EC\"/><rect x=\"58.0\" y=\"72.0\" width=\"8\" height=\"65.0\" rx=\"4\" fill=\"#15803D\"/><text x=\"80.0\" y=\"99.8\" font-size=\"15\" fill=\"#15803D\" font-weight=\"700\" text-anchor=\"start\">1. Your phone's</text><text x=\"80.0\" y=\"119.2\" font-size=\"15\" fill=\"#15803D\" font-weight=\"700\" text-anchor=\"start\">hotspot</text><text x=\"270.0\" y=\"109.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Protected by a strong password. You control this network.</text><rect x=\"58.0\" y=\"147.0\" width=\"718.0\" height=\"65.0\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"58.0\" y=\"147.0\" width=\"196\" height=\"65.0\" rx=\"10\" fill=\"#FDF3E3\"/><rect x=\"58.0\" y=\"147.0\" width=\"8\" height=\"65.0\" rx=\"4\" fill=\"#B45309\"/><text x=\"80.0\" y=\"174.8\" font-size=\"15\" fill=\"#B45309\" font-weight=\"700\" text-anchor=\"start\">2. Public Wi-Fi +</text><text x=\"80.0\" y=\"194.2\" font-size=\"15\" fill=\"#B45309\" font-weight=\"700\" text-anchor=\"start\">VPN</text><text x=\"270.0\" y=\"184.5\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">Switch the company VPN on before you do any work.</text><rect x=\"58.0\" y=\"222.0\" width=\"718.0\" height=\"45.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><rect x=\"58.0\" y=\"222.0\" width=\"196\" height=\"45.5\" rx=\"10\" fill=\"#EFF6FF\"/><rect x=\"58.0\" y=\"222.0\" width=\"8\" height=\"45.5\" rx=\"4\" fill=\"#2563EB\"/><text x=\"80.0\" y=\"249.8\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">3. No connection</text><text x=\"270.0\" y=\"249.8\" font-size=\"13\" fill=\"#111827\" font-weight=\"normal\" text-anchor=\"start\">If you can't connect safely, wait for sensitive work.</text><line x1=\"34.0\" y1=\"78.0\" x2=\"34.0\" y2=\"263.5\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><text x=\"26\" y=\"76\" font-size=\"11\" fill=\"#6B7280\" transform=\"rotate(-90 26 76)\" text-anchor=\"end\">Best</text><text x=\"26\" y=\"253.5\" font-size=\"11\" fill=\"#6B7280\" transform=\"rotate(-90 26 253.5)\" text-anchor=\"start\">Last resort</text></svg>",
