    afterParagraph: 5,
    svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 395\" width=\"800\" height=\"395\" role=\"img\" aria-labelledby=\"t\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"><title id=\"t\">How a ransomware attack usually unfolds: Entry; Quiet spread; Data theft; Encryption; Demand</title><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L0,10 L9,5 Z\" fill=\"#9CA3AF\"/></marker></defs><rect width=\"800\" height=\"395\" fill=\"#F9FAFB\"/><text x=\"24.0\" y=\"40.0\" font-size=\"20\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"start\">How a ransomware attack usually unfolds</text><rect x=\"24.0\" y=\"72.0\" width=\"228.0\" height=\"131.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"138.0\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"138.0\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">1</text><text x=\"138.0\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Entry</text><text x=\"138.0\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Phishing, stolen password,</text><text x=\"138.0\" y=\"187.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">unpatched system</text><rect x=\"286.0\" y=\"72.0\" width=\"228.0\" height=\"131.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"400.0\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"400.0\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">2</text><text x=\"400.0\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Quiet spread</text><text x=\"400.0\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Days or weeks exploring the</text><text x=\"400.0\" y=\"187.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">network</text><line x1=\"255.0\" y1=\"137.8\" x2=\"282.0\" y2=\"137.8\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><rect x=\"548.0\" y=\"72.0\" width=\"228.0\" height=\"131.5\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#E5E7EB\" stroke-width=\"1.5\"/><circle cx=\"662.0\" cy=\"100.0\" r=\"14\" fill=\"#2563EB\"/><text x=\"662.0\" y=\"105.0\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">3</text><text x=\"662.0\" y=\"145.0\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Data theft</text><text x=\"662.0\" y=\"170.0\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Valuable data copied out</text><line x1=\"517.0\" y1=\"137.8\" x2=\"544.0\" y2=\"137.8\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><rect x=\"155.0\" y=\"237.5\" width=\"228.0\" height=\"131.5\" rx=\"10\" fill=\"#FBEAE6\" stroke=\"#C1442D\" stroke-width=\"2\"/><circle cx=\"269.0\" cy=\"265.5\" r=\"14\" fill=\"#C1442D\"/><text x=\"269.0\" y=\"270.5\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">4</text><text x=\"269.0\" y=\"310.5\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Encryption</text><text x=\"269.0\" y=\"335.5\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Systems locked, often at night</text><text x=\"269.0\" y=\"352.5\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">or a weekend</text><rect x=\"417.0\" y=\"237.5\" width=\"228.0\" height=\"131.5\" rx=\"10\" fill=\"#FBEAE6\" stroke=\"#C1442D\" stroke-width=\"2\"/><circle cx=\"531.0\" cy=\"265.5\" r=\"14\" fill=\"#C1442D\"/><text x=\"531.0\" y=\"270.5\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">5</text><text x=\"531.0\" y=\"310.5\" font-size=\"15\" fill=\"#111827\" font-weight=\"700\" text-anchor=\"middle\">Demand</text><text x=\"531.0\" y=\"335.5\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">Ransom notes appear; systems</text><text x=\"531.0\" y=\"352.5\" font-size=\"12.5\" fill=\"#6B7280\" font-weight=\"normal\" text-anchor=\"middle\">stop</text><line x1=\"386.0\" y1=\"303.2\" x2=\"413.0\" y2=\"303.2\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/><path d=\"M662.0,205.5 V223.5 H269.0 V233.5\" fill=\"none\" stroke=\"#9CA3AF\" stroke-width=\"2\" marker-end=\"url(#ah)\"/></svg>",
